INSERT INTO `cache` VALUES ('dis-cache-category_child_page_845754e7af2047d150cc683fe02851de','O:15:\"App\\Models\\Page\":34:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:5:\"pages\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:25:{s:2:\"id\";i:4;s:5:\"title\";s:19:\"Principal\'s Message\";s:4:\"slug\";s:17:\"principal-message\";s:13:\"page_category\";s:8:\"about-us\";s:10:\"menu_title\";s:19:\"Principal\'s Message\";s:10:\"menu_order\";i:3;s:12:\"show_in_menu\";i:1;s:12:\"menu_section\";s:4:\"main\";s:12:\"external_url\";N;s:15:\"open_in_new_tab\";i:0;s:11:\"is_featured\";i:1;s:7:\"excerpt\";s:88:\"Message from Principal Hasina Mohammed on character-building and leadership development.\";s:9:\"parent_id\";i:1;s:7:\"content\";s:1598:\"<div class=\"text-center mb-8\"><p class=\"text-lg font-semibold text-aisd-midnight\">Hasina Mohammed</p><p class=\"text-gray-600\">Principal</p></div><p class=\"text-xl font-bold text-aisd-midnight mb-6 text-center\">\"Our foundation is morality. Our goal is leadership.\"</p><p>Welcome to Duha International school--a place where we believe that a truly excellent education is built on a strong foundation of morality and character. While academic achievement is vital, we know that to succeed in the wider world, our students need more than just good grades; they need a well-developed moral compass.</p><p>At DIS, we intentionally weave the teaching of core values into every aspect of school life, from the classroom to the sports field. Our focus is on cultivating traits that matter most: integrity, empathy, respect, responsibility, and perseverance. We are not just teaching students what to think, but how to be thoughtful, ethical, and engaged members of their community.</p><p>We believe that moral education is the bedrock of leadership. By fostering an environment where students learn to make principled decisions, treat others with kindness, and own their actions, we are preparing them to be confident, contributing citizens and the compassionate leaders of tomorrow.</p><p>Choosing a school is choosing a culture. If you seek a supportive community where your child\'s character will be nurtured with the same dedication as their intellectual growth, we invite you to join us. We look forward to partnering with you in this most important endeavor of shaping great minds and good hearts.</p>\";s:10:\"hero_image\";N;s:14:\"featured_image\";N;s:10:\"hero_badge\";s:27:\"Hasina Mohammed - Principal\";s:13:\"hero_subtitle\";s:53:\"\"Our foundation is morality. Our goal is leadership.\"\";s:10:\"meta_title\";s:47:\"Principal\'s Message - Duha International School\";s:16:\"meta_description\";s:126:\"Read the message from Principal Hasina Mohammed on character-building and leadership development at Duha International School.\";s:12:\"seo_keywords\";N;s:12:\"is_published\";i:1;s:12:\"published_at\";s:19:\"2025-11-27 02:11:12\";s:10:\"created_at\";s:19:\"2025-11-27 02:11:12\";s:10:\"updated_at\";s:19:\"2025-11-27 02:11:12\";}s:11:\"\0*\0original\";a:25:{s:2:\"id\";i:4;s:5:\"title\";s:19:\"Principal\'s Message\";s:4:\"slug\";s:17:\"principal-message\";s:13:\"page_category\";s:8:\"about-us\";s:10:\"menu_title\";s:19:\"Principal\'s Message\";s:10:\"menu_order\";i:3;s:12:\"show_in_menu\";i:1;s:12:\"menu_section\";s:4:\"main\";s:12:\"external_url\";N;s:15:\"open_in_new_tab\";i:0;s:11:\"is_featured\";i:1;s:7:\"excerpt\";s:88:\"Message from Principal Hasina Mohammed on character-building and leadership development.\";s:9:\"parent_id\";i:1;s:7:\"content\";s:1598:\"<div class=\"text-center mb-8\"><p class=\"text-lg font-semibold text-aisd-midnight\">Hasina Mohammed</p><p class=\"text-gray-600\">Principal</p></div><p class=\"text-xl font-bold text-aisd-midnight mb-6 text-center\">\"Our foundation is morality. Our goal is leadership.\"</p><p>Welcome to Duha International school--a place where we believe that a truly excellent education is built on a strong foundation of morality and character. While academic achievement is vital, we know that to succeed in the wider world, our students need more than just good grades; they need a well-developed moral compass.</p><p>At DIS, we intentionally weave the teaching of core values into every aspect of school life, from the classroom to the sports field. Our focus is on cultivating traits that matter most: integrity, empathy, respect, responsibility, and perseverance. We are not just teaching students what to think, but how to be thoughtful, ethical, and engaged members of their community.</p><p>We believe that moral education is the bedrock of leadership. By fostering an environment where students learn to make principled decisions, treat others with kindness, and own their actions, we are preparing them to be confident, contributing citizens and the compassionate leaders of tomorrow.</p><p>Choosing a school is choosing a culture. If you seek a supportive community where your child\'s character will be nurtured with the same dedication as their intellectual growth, we invite you to join us. We look forward to partnering with you in this most important endeavor of shaping great minds and good hearts.</p>\";s:10:\"hero_image\";N;s:14:\"featured_image\";N;s:10:\"hero_badge\";s:27:\"Hasina Mohammed - Principal\";s:13:\"hero_subtitle\";s:53:\"\"Our foundation is morality. Our goal is leadership.\"\";s:10:\"meta_title\";s:47:\"Principal\'s Message - Duha International School\";s:16:\"meta_description\";s:126:\"Read the message from Principal Hasina Mohammed on character-building and leadership development at Duha International School.\";s:12:\"seo_keywords\";N;s:12:\"is_published\";i:1;s:12:\"published_at\";s:19:\"2025-11-27 02:11:12\";s:10:\"created_at\"