INSERT INTO `events` VALUES (1,'Annual Science Fair 2025','annual-science-fair-2025','Join us for our annual science fair showcasing innovative projects from students across all grade levels.','<p>Our Annual Science Fair is one of the most anticipated events of the year. Students from all grade levels will showcase their innovative science projects, experiments, and research findings. This event promotes scientific inquiry, critical thinking, and creativity among our students.</p>\n                \n                <h3>Event Highlights:</h3>\n                <ul>\n                    <li>Student project presentations</li>\n                    <li>Interactive science demonstrations</li>\n                    <li>Guest judges from the scientific community</li>\n                    <li>Prizes for outstanding projects</li>\n                    <li>Open to parents and community members</li>\n                </ul>\n                \n                <p><strong>Date:</strong> March 15, 2025<br>\n                <strong>Time:</strong> 9:00 AM - 3:00 PM<br>\n                <strong>Location:</strong> School Auditorium and Science Labs</p>','<p>Our Annual Science Fair is one of the most anticipated events of the year. Students from all grade levels will showcase their innovative science projects, experiments, and research findings. This event promotes scientific inquiry, critical thinking, and creativity among our students.</p>','2026-01-27 09:00:00','2026-01-27 09:00:00',NULL,'School Auditorium','Academic',1,1,'published','2025-11-26 20:11:00','2025-11-26 20:11:13','2025-11-26 20:56:37'),(2,'Quran Memorization Competition','quran-memorization-competition','Annual Quran memorization competition for students to showcase their Hifz achievements.','<p>Our annual Quran Memorization Competition celebrates the achievements of our students in memorizing the Holy Quran. This event recognizes the dedication and effort of our Hifz students and encourages others to follow in their footsteps.</p>\n                \n                <h3>Competition Categories:</h3>\n                <ul>\n                    <li>Juz Amma (30th Juz)</li>\n                    <li>Selected Surahs</li>\n                    <li>Full Quran (Hifz)</li>\n                    <li>Recitation with Tajweed</li>\n                </ul>\n                \n                <p><strong>Date:</strong> April 10, 2025<br>\n                <strong>Time:</strong> 10:00 AM - 2:00 PM<br>\n                <strong>Location:</strong> School Masjid</p>','<p>Our annual Quran Memorization Competition celebrates the achievements of our students in memorizing the Holy Quran. This event recognizes the dedication and effort of our Hifz students and encourages others to follow in their footsteps.</p>','2026-02-27 10:00:00','2026-02-27 10:00:00',NULL,'School Masjid','Islamic',1,1,'published','2025-11-26 20:11:00','2025-11-26 20:11:13','2025-11-26 20:55:41'),(3,'Sports Day 2025','sports-day-2025','Annual sports day featuring various athletic competitions and team events.','<p>Join us for our annual Sports Day, a day filled with excitement, competition, and team spirit. Students will participate in various athletic events including track and field, team sports, and fun activities.</p>\n                \n                <h3>Events Include:</h3>\n                <ul>\n                    <li>Track and field competitions</li>\n                    <li>Football and basketball matches</li>\n                    <li>Relay races</li>\n                    <li>Fun activities for younger students</li>\n                    <li>Award ceremony</li>\n                </ul>\n                \n                <p><strong>Date:</strong> May 20, 2025<br>\n                <strong>Time:</strong> 8:00 AM - 4:00 PM<br>\n                <strong>Location:</strong> School Sports Ground</p>','<p>Join us for our annual Sports Day, a day filled with excitement, competition, and team spirit. Students will participate in various athletic events including track and field, team sports, and fun activities.</p>','2026-03-27 08:00:00','2026-03-27 08:00:00',NULL,'School Sports Ground','Sports',1,1,'published','2025-11-26 20:11:00','2025-11-26 20:11:13','2025-11-26 20:20:01'),(4,'Parent-Teacher Conference','parent-teacher-conference','Scheduled parent-teacher conferences to discuss student progress and academic performance.','<p>We invite all parents to attend our scheduled parent-teacher conferences. This is an opportunity to meet with your child\'s teachers, discuss academic progress, and address any concerns or questions.</p>\n                \n                <h3>What to Expect:</h3>\n                <ul>\n                    <li>Individual meetings with subject teachers</li>\n                    <li>Review of academic progress reports</li>\n                    <li>Discussion of student strengths and areas for improvement</li>\n                    <li>Goal setting for the next term</li>\n                </ul>\n                \n                <p><strong>Date:</strong> February 25, 2025<br>\n                <strong>Time:</strong> 2:00 PM - 6:00 PM<br>\n                <strong>Location:</strong> School Classrooms</p>\n                \n                <p><em>Please schedule your appointment in advance through the school office.</em></p>','<p>We invite all parents to attend our scheduled parent-teacher conferences. This is an opportunity to meet with your child\'s teachers, discuss academic progress, and address any concerns or questions.</p>','2025-12-27 14:00:00','2025-12-27 14:00:00',NULL,'School Classrooms','Academic',0,1,'published','2025-11-26 20:11:00','2025-11-26 20:11:13','2025-11-26 20:39:34'),(5,'Islamic Art Exhibition','islamic-art-exhibition','Showcase of Islamic art and calligraphy created by our talented students.','<p>Our Islamic Art Exhibition celebrates the rich tradition of Islamic art and calligraphy. Students from all grade levels will display their artwork, including Arabic calligraphy, geometric patterns, and Islamic-inspired designs.</p>\n                \n                <h3>Exhibition Features:</h3>\n                <ul>\n                    <li>Arabic calligraphy displays</li>\n                    <li>Geometric pattern artwork</li>\n                    <li>Islamic architecture models</li>\n                    <li>Student presentations on Islamic art history</li>\n                </ul>\n                \n                <p><strong>Date:</strong> June 5, 2025<br>\n                <strong>Time:</strong> 10:00 AM - 4:00 PM<br>\n                <strong>Location:</strong> School Art Gallery</p>','<p>Our Islamic Art Exhibition celebrates the rich tradition of Islamic art and calligraphy. Students from all grade levels will display their artwork, including Arabic calligraphy, geometric patterns, and Islamic-inspired designs.</p>','2026-04-27 10:00:00','2026-04-27 10:00:00',NULL,'School Art Gallery','Academic',0,1,'published','2025-11-26 20:11:00','2025-11-26 20:11:13','2025-11-26 20:56:01'),(6,'test','test','test','<p>testt</p>','<p>testt</p>','2025-11-11 10:10:00','2025-11-11 10:10:00','2025-11-27 11:10:00',NULL,'Academic',1,1,'published','2025-11-26 20:40:00','2025-11-26 20:41:51','2025-11-26 20:41:51');
