INSERT INTO `home_page_sections` VALUES (1,'hero','hero','Nurturing Brilliance,','One Child at a Time',NULL,'Duha International School provides quality Islamic and modern education that nurtures future leaders with strong moral character and academic excellence.','Learn More',NULL,'{\"badge\": \"Welcome\"}',1,1,'2025-11-26 20:11:12','2025-11-26 20:12:09'),(2,'hero_2','hero','Eat healthy','Stay healthy',NULL,'Promoting healthy living and nutrition awareness among our students through educational programs and activities.','View Activities',NULL,'{\"badge\": \"Health & Wellness\"}',2,1,'2025-11-26 20:11:12','2025-11-26 20:12:26'),(3,'hero_3','hero','Admission','Open Now',NULL,'Enroll your child in a world-class education that combines Islamic values with modern academic excellence.','Apply Online',NULL,'{\"badge\": \"Admissions\"}',3,1,'2025-11-26 20:11:12','2025-11-26 20:12:48'),(4,'info_enrollment','info_block','Enrollment News',NULL,'Join our institution. Participate in a universe of excitement and education.','Join our institution. Participate in a universe of excitement and education.','Apply Now','/admission','{\"icon\": \"plus\"}',11,1,'2025-11-26 20:11:12','2025-11-26 20:11:12'),(5,'info_events','info_block','Regular Events',NULL,'Discover the beauty of regular Islamic events, fostering understanding, unity, and spiritual growth in a nurturing environment.','Discover the beauty of regular Islamic events, fostering understanding, unity, and spiritual growth in a nurturing environment.','View Events','/events','{\"icon\": \"calendar\"}',12,1,'2025-11-26 20:11:12','2025-11-26 20:11:12'),(6,'info_notice','info_block','Notice Board',NULL,'Stay informed with the latest announcements and upcoming news at Duha International School.','Stay informed with the latest announcements and upcoming news at Duha International School.','View Notices','/notices','{\"icon\": \"megaphone\"}',13,1,'2025-11-26 20:11:12','2025-11-26 20:11:12'),(7,'why_choose','content','Why Choose Duha',NULL,'Our comprehensive curriculum combines Cambridge education with Islamic values, ensuring students receive a well-rounded education that prepares them for the challenges of the 21st century while maintaining strong Islamic principles. We are committed to fostering global citizens who are grounded in faith and equipped with modern knowledge.','Our comprehensive curriculum combines Cambridge education with Islamic values, ensuring students receive a well-rounded education that prepares them for the challenges of the 21st century while maintaining strong Islamic principles.',NULL,NULL,'{\"image_url\": \"https://images.unsplash.com/photo-1503676260728-1c00da094a0b?w=600&h=400&fit=crop\"}',14,1,'2025-11-26 20:11:12','2025-11-26 20:11:12'),(8,'children_responsibility','content','Your Children, Our Responsibility',NULL,'<p>Welcome to Duha International School, established in 2012 in Chittagong, Bangladesh. We are dedicated to providing holistic education that combines academic excellence with moral development.</p><p>Our commitment extends beyond the classroom, focusing on Islamic values and Cambridge curriculum integration to nurture well-rounded individuals who excel both academically and spiritually.</p>','Welcome to Duha International School, established in 2012 in Chittagong, Bangladesh. We are dedicated to providing holistic education that combines academic excellence with moral development.',NULL,NULL,'{\"image_url\": \"https://images.unsplash.com/photo-1481627834876-b7833e8f5570?w=600&h=400&fit=crop\"}',15,1,'2025-11-26 20:11:12','2025-11-26 20:11:12'),(9,'values','list','Our Values',NULL,NULL,'Core values that guide our institution',NULL,NULL,'{\"values\": [\"Tawheed & God Consciousness\", \"Courage\", \"Charitable\", \"Patience\", \"Consultation\", \"Hard Work\", \"Respect\", \"Excellence\", \"Discipline\", \"Humility\", \"Gratitude\", \"Resistance to Evil\", \"Self-Control\", \"Unity in Diversity\", \"Dependency\", \"Honesty\"]}',16,1,'2025-11-26 20:11:12','2025-11-26 20:11:12'),(10,'advisors','advisors','Advisors & Board of Governors','Leadership',NULL,'Distinguished scholars, Cambridge examiners, and community leaders steward our Islamic ethos and academic rigor.',NULL,NULL,'{\"advisors\": [{\"bio\": \"Former Cambridge examiner & Islamic pedagogy researcher.\", \"name\": \"Dr. Samira Ameen\", \"role\": \"Chair, Board of Governors\", \"image\": \"images/advisors/samira.svg\", \"linkedin\": \"#\"}, {\"bio\": \"Graduate of Al-Azhar, leads Quran sciences curriculum.\", \"name\": \"Sheikh Farid Rahman\", \"role\": \"Religious Advisor\", \"image\": \"images/advisors/farid.svg\", \"linkedin\": \"#\"}, {\"bio\": \"Visionary behind Duha-inspired transformation.\", \"name\": \"Md.Hussain\", \"role\": \"Founder & Advisor\", \"image\": \"images/advisors/kawser.svg\", \"linkedin\": \"#\"}, {\"bio\": \"Leads STEAM integration across Middle & Senior school.\", \"name\": \"Ayesha Siddiqua\", \"role\": \"Academic Director\", \"image\": \"images/advisors/ayesha.svg\", \"linkedin\": \"#\"}]}',16,1,'2025-11-26 20:11:12','2025-11-26 20:11:12'),(11,'video_1','video','Academic Director & CEO','Let\'s hear from our Academic Director & CEO, Md. Neazul Hoque',NULL,NULL,NULL,NULL,'{\"video_url\": null, \"youtube_url\": null}',17,1,'2025-11-26 20:11:12','2025-11-26 20:11:12'),(12,'video_2','video','Inter-School Quran Competition','Let\'s relive the spirit of the Inter-School Quran Competition!',NULL,NULL,NULL,NULL,'{\"video_url\": null, \"youtube_url\": \"https://www.youtube.com/watch?v=example\"}',18,1,'2025-11-26 20:11:12','2025-11-26 20:11:12'),(13,'achievements','achievements','Recognising Our Learners','Highlights',NULL,'From Qur\'an recitation championships to Cambridge distinctions, our students lead locally and globally.',NULL,NULL,'{\"subtitle\": \"Highlights\", \"achievements\": [{\"copy\": \"Multiple \\\"Top in Bangladesh\\\" awards in Mathematics & English.\", \"icon\": \"M9 12l2 2 4-4M7.835 4.697a3.42 3.42 0 001.946-.806 3.42 3.42 0 014.438 0 3.42 3.42 0 001.946.806 3.42 3.42 0 013.138 3.138 3.42 3.42 0 00.806 1.946 3.42 3.42 0 010 4.438 3.42 3.42 0 00-.806 1.946 3.42 3.42 0 01-3.138 3.138 3.42 3.42 0 00-1.946.806 3.42 3.42 0 01-4.438 0 3.42 3.42 0 00-1.946-.806 3.42 3.42 0 01-3.138-3.138 3.42 3.42 0 00-.806-1.946 3.42 3.42 0 010-4.438 3.42 3.42 0 00.806-1.946 3.42 3.42 0 013.138-3.138z\", \"badge\": \"IGCSE\", \"title\": \"Cambridge Top Achievers\"}, {\"copy\": \"Gold medal at the 2024 Kuala Lumpur Tilawah.\", \"icon\": \"M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z\", \"badge\": \"Hifz\", \"title\": \"International Quran Recital\"}, {\"copy\": \"Solar desalination project crowned champion at city science fair.\", \"icon\": \"M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z\", \"badge\": \"STEM\", \"title\": \"STEM Innovation Fair\"}, {\"copy\": \"Best Delegate recognition for our secondary students.\", \"icon\": \"M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z\", \"badge\": \"Leadership\", \"title\": \"Model OIC Summit\"}]}',4,1,'2025-11-26 20:11:12','2025-11-26 20:11:12'),(14,'stats_main','stats','Our School in Numbers',NULL,NULL,'A snapshot of growth across our Cambridge and Islamic streams.',NULL,NULL,'{\"cta\": {\"title\": \"Join a community grounded in faith and excellence.\", \"button1\": {\"link\": \"/campus\", \"text\": \"Schedule a Visit\"}, \"button2\": {\"link\": \"/admission\", \"text\": \"Talk to Admissions\"}}, \"stats\": [{\"copy\": \"Across Early Years to A-Level\", \"icon\": \"M13 6a3 3 0 11-6 0 3 3 0 016 0zM18 8a2 2 0 11-4 0 2 2 0 014 0zM14 15a4 4 0 00-8 0v3h8v-3z\", \"label\": \"Students\", \"value\": \"1200+\"}, {\"copy\": \"Certified international faculty\", \"icon\": \"M5 13l4 4L19 7\", \"label\": \"Teachers\", \"value\": \"85\"}, {\"copy\": \"Established excellence\", \"icon\": \"M9 12l2 2 4-4\", \"label\": \"Years\", \"value\": \"15+\"}, {\"copy\": \"IGCSE & A-Level results\", \"icon\": \"M5 13l4 4L19 7\", \"label\": \"Success Rate\", \"value\": \"98%\"}], \"subtitle\": \"Impact\"}',5,1,'2025-11-26 20:11:12','2025-11-26 20:11:12'),(15,'parallax_experience','parallax',NULL,NULL,NULL,NULL,NULL,NULL,'{\"cta\": {\"link\": \"/campus\", \"text\": \"Explore Our Campus\"}, \"badge\": \"Experience\", \"title\": \"Where tradition meets innovation every school day.\", \"description\": \"Borrowing Duha\'s parallax rhythm, this slice of campus life highlights collaborative learning pods, Arabic storytelling corners, and maker labs.\", \"feature_pills\": [{\"text\": \"Dedicated Musalla & Hifz Pods\"}, {\"text\": \"Robotics & Design Thinking Lab\"}, {\"text\": \"Outdoor Play Courts\"}], \"use_default_image\": true}',8,1,'2025-11-26 20:11:12','2025-11-26 20:11:12'),(16,'competitions','competitions','Excellence in Academic & Islamic Pursuits',NULL,NULL,'Celebrating our students\' achievements in tournaments, Olympiads, and Qur\'anic competitions that showcase both knowledge and character.',NULL,NULL,'{\"title\": \"Excellence in Academic & Islamic Pursuits\", \"description\": \"Celebrating our students\' achievements in tournaments, Olympiads, and Qur\'anic competitions that showcase both knowledge and character.\", \"competitions\": [{\"copy\": \"Students deliver khutbah-style speeches judged by scholars, developing eloquence and understanding of Islamic principles.\", \"icon\": \"M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z\", \"title\": \"Arabic Oratory League\", \"iconBg\": \"#173B7A\", \"gradient\": \"linear-gradient(135deg, #173B7A, #0F224C)\"}, {\"copy\": \"Regional gold in junior category with perfect logic scores, demonstrating analytical excellence and problem-solving prowess.\", \"icon\": \"M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z\", \"title\": \"Mathematics Olympiad\", \"iconBg\": \"#0C1B3D\", \"gradient\": \"linear-gradient(135deg, #0C1B3D, #173B7A)\"}, {\"copy\": \"National runner-up with flawless maqamat transitions, honoring the beauty and precision of Qur\'anic recitation.\", \"icon\": \"M9 19V6l12-3v13M9 19c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zm12-3c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zM9 10l12-3\", \"title\": \"Qira\'ah Championship\", \"iconBg\": \"#0F224C\", \"gradient\": \"linear-gradient(135deg, #0F224C, #0C1B3D)\"}]}',9,1,'2025-11-26 20:11:12','2025-11-26 20:11:12'),(17,'academic_programs','programs','Our Academic Programs',NULL,NULL,'Comprehensive educational pathways designed to nurture intellectual growth, spiritual development, and global competency from early years through secondary education.',NULL,NULL,'{\"title\": \"Our Academic Programs\", \"programs\": [{\"icon\": \"M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.746 0 3.332.477 4.5 1.253v13C19.832 18.477 18.246 18 16.5 18c-1.746 0-3.332.477-4.5 1.253\", \"title\": \"Early Years Foundation\", \"features\": [{\"text\": \"Play-based learning approach\"}, {\"text\": \"Qur\'an & Arabic introduction\"}, {\"text\": \"Character building activities\"}, {\"text\": \"Cambridge assessment framework\"}], \"description\": \"Cambridge Early Years Foundation Stage curriculum with Islamic values integration, focusing on play-based learning and character development.\", \"grade_range\": \"Play, Nursery, Reception\", \"icon_bg_color\": \"#6EC1F5\"}, {\"icon\": \"M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01\", \"title\": \"Cambridge Primary\", \"features\": [{\"text\": \"Cambridge Primary Checkpoint\"}, {\"text\": \"Integrated Islamic curriculum\"}, {\"text\": \"Hifz & Nazira tracks\"}, {\"text\": \"STEAM enrichment programs\"}], \"description\": \"Cambridge Primary curriculum (Key Stage 1 & 2) with comprehensive Islamic Studies, Arabic language, and Hifz program options.\", \"grade_range\": \"Class 1 to 6\", \"icon_bg_color\": \"#173B7A\"}, {\"icon\": \"M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.746 0 3.332.477 4.5 1.253v13C19.832 18.477 18.246 18 16.5 18c-1.746 0-3.332.477-4.5 1.253\", \"title\": \"Cambridge Secondary\", \"features\": [{\"text\": \"Cambridge IGCSE preparation\"}, {\"text\": \"Advanced Islamic Sciences\"}, {\"text\": \"Leadership development\"}, {\"text\": \"Career guidance & counseling\"}], \"description\": \"Cambridge Lower Secondary and IGCSE programs with advanced Islamic Studies, preparing students for international qualifications.\", \"grade_range\": \"Class 7 to 10\", \"icon_bg_color\": \"#0C1B3D\"}, {\"icon\": \"M9 12l2 2 4-4M7.835 4.697a3.42 3.42 0 001.946-.806 3.42 3.42 0 014.438 0 3.42 3.42 0 001.946.806 3.42 3.42 0 013.138 3.138 3.42 3.42 0 00.806 1.946 3.42 3.42 0 010 4.438 3.42 3.42 0 00-.806 1.946 3.42 3.42 0 01-3.138 3.138 3.42 3.42 0 00-1.946.806 3.42 3.42 0 01-4.438 0 3.42 3.42 0 00-1.946-.806 3.42 3.42 0 01-3.138-3.138 3.42 3.42 0 00-.806-1.946 3.42 3.42 0 010-4.438 3.42 3.42 0 00.806-1.946 3.42 3.42 0 013.138-3.138z\", \"title\": \"Cambridge A-Level\", \"features\": [{\"text\": \"AS & A-Level qualifications\"}, {\"text\": \"Subject specialization\"}, {\"text\": \"University preparation\"}, {\"text\": \"Islamic leadership program\"}], \"description\": \"Advanced Level program with subject specialization, Islamic leadership training, and university preparation.\", \"grade_range\": \"Class 11 to 12\", \"icon_bg_color\": \"#F4C430\"}], \"subtitle\": \"Academic Excellence\", \"description\": \"Comprehensive educational pathways designed to nurture intellectual growth, spiritual development, and global competency from early years through secondary education.\", \"special_features\": {\"cta\": {\"link\": \"/academics\", \"text\": \"Explore Programs\"}, \"title\": \"Beyond the Classroom\", \"features\": [{\"icon\": \"M9 19V6l12-3v13M9 19c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zm12-3c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zM9 10l12-3\", \"title\": \"Hifz Program\", \"subtitle\": \"Qur\'an Memorization\"}, {\"icon\": \"M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z\", \"title\": \"STEAM Labs\", \"subtitle\": \"Innovation & Design\"}, {\"icon\": \"M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z\", \"title\": \"Leadership\", \"subtitle\": \"Service Learning\"}, {\"icon\": \"M3 5h12M9 3v2m1.048 9.5A18.022 18.022 0 016.412 9m6.088 9h7M11 21l5-10 5 10M12.751 5C11.783 10.77 8.07 15.61 3 18.129\", \"title\": \"Arabic Excellence\", \"subtitle\": \"Language Mastery\"}], \"description\": \"Our holistic approach extends beyond academics, offering specialized programs that develop character, leadership, and global citizenship.\"}}',10,1,'2025-11-26 20:11:12','2025-11-26 20:11:12'),(18,'vision','vision_mission',NULL,NULL,NULL,'Rooted in Islamic values and guided by the Qur\'an and Sunnah, we unite world-class Cambridge education with comprehensive Tarbiyah to nurture God-conscious scholars, compassionate leaders, and ethical global citizens.',NULL,NULL,'{\"features\": [{\"text\": \"Qur\'an & Sunnah Foundation\"}, {\"text\": \"Cambridge IGCSE & A-Level\"}, {\"text\": \"Hifz, Tajweed & Arabic Excellence\"}, {\"text\": \"Islamic Character & Leadership\"}, {\"text\": \"Service to Ummah & Humanity\"}], \"badge_text\": \"Our Islamic Charter\", \"core_values\": [{\"value\": \"Tawheed - Oneness of Allah\"}, {\"value\": \"Taqwa - God Consciousness\"}, {\"value\": \"Ihsan - Excellence in All\"}, {\"value\": \"Amanah - Trust & Responsibility\"}, {\"value\": \"Adab - Prophetic Manners\"}, {\"value\": \"Ilm - Pursuit of Knowledge\"}, {\"value\": \"Sabr - Patience & Perseverance\"}, {\"value\": \"Shukr - Gratitude to Allah\"}, {\"value\": \"Rahmah - Mercy & Compassion\"}, {\"value\": \"Khidmah - Service to Others\"}], \"image_title\": \"Our Islamic Campus\", \"vision_text\": \"To be a beacon of Islamic education excellence, cultivating generations of God-conscious learners who embody Taqwa, pursue knowledge with Ihsan, and lead with wisdom, integrity, and compassion to serve humanity and please Allah (SWT).\", \"mission_text\": \"To provide holistic Islamic education that seamlessly integrates Cambridge academic excellence with Qur\'anic sciences, Arabic mastery, and prophetic character development—preparing students to excel in both Dunya and Akhirah while serving as ambassadors of Islam.\", \"values_title\": \"Islamic Core Values\", \"vision_title\": \"Our Vision\", \"heading_line1\": \"Nurturing Faith,\", \"heading_line2\": \"Inspiring Excellence\", \"mission_title\": \"Our Mission\", \"image_subtitle\": \"Where Iman meets Innovation\"}',3,1,'2025-11-26 20:11:12','2025-11-26 20:11:12'),(19,'introduction','content','To create a group of specialized Islamic scholars.',NULL,'<p>Duha International School was conceived with a clear vision: to create a group of specialized Islamic scholars who are well-versed in both traditional Islamic knowledge and modern academic disciplines. Our founders recognized the need for an educational institution that bridges the gap between Islamic scholarship and contemporary learning.</p><p>The academy commenced its operations with a commitment to excellence in both Islamic and modern education. We believe that true education must encompass both spiritual and intellectual development, preparing students to excel in this world while maintaining strong connections to their faith and values.</p>','Duha International School was established with the vision of providing quality Islamic and modern education. Our curriculum combines traditional Islamic teachings with contemporary academic excellence.','Read More',NULL,'[]',10,1,'2025-11-26 20:11:13','2025-11-26 20:13:37'),(20,'testimonials','testimonials','What Parents Say About Duha International School',NULL,NULL,'Hear from parents about their experience with Duha International School',NULL,NULL,'{\"testimonials\": [{\"role\": \"Parent\", \"quote\": \"Duha International School has provided excellent education for my child. The combination of Islamic and modern curriculum is outstanding. My child has shown remarkable improvement in both academic performance and character development.\", \"author\": \"Md. Shamimul Islam\", \"avatar\": null}, {\"role\": \"Parent\", \"quote\": \"As a parent, I am impressed by the dedication of the teachers and the holistic approach to education. The school truly nurtures both academic excellence and Islamic values.\", \"author\": \"Fatima Begum\", \"avatar\": null}, {\"role\": \"Parent\", \"quote\": \"Duha International School has created a perfect balance between Islamic education and modern learning. My children are thriving academically while maintaining strong Islamic principles.\", \"author\": \"Ahmed Hassan\", \"avatar\": null}]}',20,1,'2025-11-26 20:11:13','2025-11-26 20:11:13'),(21,'partners','partners','Our Partners',NULL,NULL,'We are proud to be associated with leading organizations worldwide.',NULL,NULL,'{\"partners\": [{\"link\": \"#\", \"logo\": null, \"name\": \"SADAGAH\"}, {\"link\": \"#\", \"logo\": null, \"name\": \"ILANNOOR INSTITUTE\"}, {\"link\": \"#\", \"logo\": null, \"name\": \"VISION\"}]}',21,1,'2025-11-26 20:11:13','2025-11-26 20:11:13'),(22,'videos','videos','Recent Videos',NULL,NULL,'Watch our latest videos showcasing student achievements and activities',NULL,NULL,'{\"main_video\": {\"title\": \"Our Duha\", \"thumbnail\": \"http://127.0.0.1:8000//storage/15/extracted-199.png\", \"youtube_id\": \"0Zv1-2OnTA0\"}, \"recent_videos\": [{\"title\": \"Upgrade Your Islamic Vocabularies | NUSAIFA AMATULLAH ASMATH & Sayra Binte Glas | Class Two\", \"thumbnail\": null, \"youtube_id\": \"dQw4w9WgXcQ\"}, {\"title\": \"Arabic Speech by Afra Binte Aman on My Hobby\", \"thumbnail\": null, \"youtube_id\": \"dQw4w9WgXcQ\"}, {\"title\": \"Hadith Memorization Exam | Azhar Md. Muhtadi Amin | Student of Tafheez Section\", \"thumbnail\": null, \"youtube_id\": \"dQw4w9WgXcQ\"}]}',19,1,'2025-11-26 20:11:13','2025-11-26 20:44:50'),(23,'events','events','Campus Activities & Events',NULL,NULL,'Control events section display settings','View All Events','/events','{\"items_count\": \"6\", \"layout_style\": \"grid\", \"title_override\": \"test\"}',15,1,'2025-11-26 20:42:25','2025-11-26 20:42:39'),(24,'news','news','Recent News',NULL,NULL,'Control news/notices section display settings','View All News','/notices','{\"items_count\": 6, \"layout_style\": \"grid\", \"title_override\": null}',17,1,'2025-11-26 20:46:56','2025-11-26 20:46:56');
