INSERT INTO `notices` VALUES (1,'Admission Open for Academic Year 2025-2026','admission-open-2025-2026','We are now accepting applications for the academic year 2025-2026. Limited seats available.','<p>Duha International School is pleased to announce that admissions are now open for the academic year 2025-2026. We welcome applications from students seeking quality Islamic and Cambridge curriculum education.</p><p>\r\n                \r\n                </p><h3>Admission Process:</h3><p>\r\n                </p><p><br></p><p>\r\n                \r\n                </p><h3>Required Documents:</h3><p>\r\n                </p><p><br></p><p>\r\n                \r\n                </p><p>For more information, please contact our admissions office or visit our website.</p><p>\r\n                \r\n                </p><p><strong>Deadline:</strong> March 31, 2025</p>','Admission',1,1,'2025-11-26 20:11:00','2025-11-26 20:11:13','2025-11-26 20:47:13'),(2,'School Holiday - Eid al-Fitr','school-holiday-eid-al-fitr','School will be closed for Eid al-Fitr celebrations. Classes will resume on the following week.','<p>In observance of Eid al-Fitr, Duha International School will be closed from <strong>April 10, 2025 to April 14, 2025</strong>.</p><p>\r\n                \r\n                </p><p>Classes will resume on <strong>Monday, April 15, 2025</strong>.</p><p>\r\n                \r\n                </p><p>We wish all our students, parents, and staff a blessed and joyous Eid celebration.</p><p>\r\n                \r\n                </p><p><em>Eid Mubarak!</em></p>','Holiday',1,1,'2025-11-26 20:11:00','2025-11-26 20:11:13','2025-11-26 20:58:10'),(3,'Mid-Term Examination Schedule','mid-term-examination-schedule','Mid-term examinations will be held from February 10-20, 2025. Please review the schedule carefully.','<p>The mid-term examination schedule for the current academic term has been published. All students are required to review the schedule and prepare accordingly.</p><p>\r\n                \r\n                </p><h3>Important Dates:</h3><p>\r\n                </p><p><br></p><p>\r\n                \r\n                </p><h3>Examination Guidelines:</h3><p>\r\n                </p><p><br></p><p>\r\n                \r\n                </p><p>The detailed schedule is available on the school portal and notice boards.</p>','Academic',1,1,'2025-11-26 20:11:00','2025-11-26 20:11:13','2025-11-26 20:59:42'),(4,'Library Hours Extended','library-hours-extended','School library will now be open until 5:00 PM on weekdays to accommodate students.','<p>We are pleased to announce that the school library hours have been extended to better serve our students.</p><p>\r\n                \r\n                </p><h3>New Library Hours:</h3><p>\r\n                </p><p><br></p><p>\r\n                \r\n                </p><p>The extended hours will allow students more time for research, study, and reading. Library staff will be available to assist students during these hours.</p><p>\r\n                \r\n                </p><p>We encourage all students to make use of this valuable resource.</p>','General',0,1,'2025-11-26 20:11:00','2025-11-26 20:11:13','2025-11-26 20:58:24'),(5,'Career Opportunities - Teaching Positions Available','career-opportunities-teaching-positions','We are seeking qualified and dedicated teachers to join our team. Multiple positions available.','<p>Duha International School is looking for passionate and qualified educators to join our teaching team.</p><p>\r\n                \r\n                </p><h3>Available Positions:</h3><p>\r\n                </p><p><br></p><p>\r\n                \r\n                </p><h3>Requirements:</h3><p>\r\n                </p><p><br></p><p>\r\n                \r\n                </p><p>Interested candidates should submit their applications through our careers portal or email to career@duhaschool.com</p><p>\r\n                \r\n                </p><p><strong>Application Deadline:</strong> March 15, 2025</p>','Career',1,1,'2025-11-26 20:11:00','2025-11-26 20:11:13','2025-11-26 20:59:32');
/*!40000 ALTER TABLE `notices` ENABLE KEYS */;
