INSERT INTO `site_settings` VALUES (1,'Duha International School','Duha International School','Duha International School was established with the vision of providing quality Islamic and modern education.',NULL,NULL,NULL,'2025-11-26 20:11:10','2025-11-26 20:11:42','Nurturing Brilliance, One Child at a Time','Duha International School was established with the vision of providing quality Islamic and modern education. Our curriculum combines traditional Islamic teachings with contemporary academic excellence.',NULL,NULL,'info@zaitoonacademy.com','zaitoonacademy1@gmail.com','+880 1748306492','+880 1708933187','Jalalabad H/S, Jalalabad Housing Society, Sector-1, Road-1, House-10, Khulshi, Chattogram, Bangladesh','Sunday - Thursday\n8:00 AM - 2:00 PM\n\nFriday & Saturday\nClosed','{\"twitter\": null, \"youtube\": \"https://www.youtube.com/@zaitoonacademy\", \"facebook\": \"https://www.facebook.com/zaitoonacademy\", \"instagram\": \"https://www.instagram.com/zaitoonacademy\"}','USD','en',NULL,'UTC','Duha International School - Nurturing Brilliance, One Child at a Time','Duha International School provides quality Islamic and modern education. Our curriculum combines traditional Islamic teachings with contemporary academic excellence.','Duha International School, Islamic Education, Modern Education, Chattogram, Bangladesh, Islamic School','Duha International School - Nurturing Brilliance, One Child at a Time','Duha International School provides quality Islamic and modern education. Our curriculum combines traditional Islamic teachings with contemporary academic excellence.',NULL,NULL,0,NULL,NULL,NULL,NULL,'© {year} Duha International School. All Rights Reserved.','#008236','#0f3d30','#fbbf24',NULL,NULL,NULL,NULL,NULL);
/*!40000 ALTER TABLE `site_settings` ENABLE KEYS */;
