INSERT INTO `staff` VALUES (1,'Principal','Principal','Leading Duha International School with dedication and commitment to educational excellence.','principal@zaitoonacademy.com','+880 1748306492','{\"twitter\": null, \"facebook\": null, \"linkedin\": null, \"instagram\": null}',1,2,'2025-11-26 20:11:13','2025-11-26 21:02:26'),(2,'Mrs. Fatima Rahman','Vice Principal','Mrs. Fatima Rahman has been with Duha International School since its inception. She holds a Master\'s degree in Education and specializes in curriculum development. She is passionate about student welfare and academic excellence.','viceprincipal@almaghribschool.com','+880-31-1234568',NULL,1,2,'2025-11-26 20:11:13','2025-11-26 20:11:13'),(3,'Ustadh Ahmad Hassan','Head of Islamic Studies','Ustadh Ahmad Hassan is a renowned Islamic scholar with extensive knowledge in Quranic studies, Hadith, and Islamic jurisprudence. He has memorized the entire Quran and holds Ijazah in multiple Qira\'at. He is dedicated to instilling Islamic values in our students.','islamicstudies@almaghribschool.com','+880-31-1234569',NULL,1,3,'2025-11-26 20:11:13','2025-11-26 20:11:13'),(4,'Mr. John Smith','Head of Academics','Mr. John Smith is an experienced educator with expertise in Cambridge International Curriculum. He holds a Master\'s degree in Education and has been instrumental in developing our academic programs. He ensures that our students receive world-class education standards.','academics@almaghribschool.com','+880-31-1234570',NULL,1,4,'2025-11-26 20:11:13','2025-11-26 20:11:13'),(5,'Mrs. Sarah Khan','Head of Primary School','Mrs. Sarah Khan specializes in early childhood and primary education. With over 15 years of experience, she creates nurturing learning environments for young students. She holds a Master\'s degree in Early Childhood Education and is passionate about holistic child development.','primary@almaghribschool.com','+880-31-1234571',NULL,1,5,'2025-11-26 20:11:13','2025-11-26 20:11:13'),(6,'Mr. David Williams','Head of Science Department','Mr. David Williams brings extensive experience in science education and laboratory management. He holds a Master\'s degree in Physics and has been teaching for over 18 years. He is committed to making science accessible and exciting for all students.','science@almaghribschool.com','+880-31-1234572',NULL,1,6,'2025-11-26 20:11:13','2025-11-26 20:11:13'),(7,'Chairman','Chairman','Duha International School is committed to providing excellence in both Islamic and modern education. Our curriculum is designed to nurture well-rounded individuals who excel academically while maintaining strong Islamic values. We believe in creating a learning environment where students can grow intellectually, spiritually, and morally, preparing them to be future leaders who contribute positively to society.','chairman@zaitoonacademy.com','+880 1748306492','{\"twitter\": null, \"facebook\": null, \"linkedin\": null, \"instagram\": null}',1,1,'2025-11-26 20:11:13','2025-11-26 20:14:16');
/*!40000 ALTER TABLE `staff` ENABLE KEYS */;
UNLOCK TABLES;

